data = []
for i, item in enumerate(raw_records, 1):
    cid = f"PMP-{2026}-{i:04d}"
    text, category, sentiment, priority, location, mode = item
    data.append({
        "complaint_id": cid,
        "complaint_text": text,
        "service_category": category,
        "sentiment": sentiment,
        "priority": priority,
        "location": location,
        "transit_mode": mode
    })

df = pd.DataFrame(data)
df.to_csv("pune_transport_complaints.csv", index=False)
print(f"Generated {len(df)} realistic Pune public transport complaints saved to pune_transport_complaints.csv")
